  const form = useForm<Record<string, unknown>>({ resolver: zodResolver(programSchema), defaultValues: { name: "Regular Day Programme", academicYearId: "", primary: "true", daysOfWeek: "Monday, Tuesday, Wednesday, Thursday, Friday", startTime: "09:00", endTime: "16:00" } });
  useEffect(() => { if (query.data) form.reset({ name: query.data.name, academicYearId: query.data.academicYearId, primary: String(query.data.isPrimary), daysOfWeek: toProgramViewModel(query.data).daysOfWeek.join(", "), startTime: query.data.startTime, endTime: query.data.endTime }); }, [query.data]);
  if (editing && (query.isLoading || years.isLoading)) return <Loading />;
  if (years.isError) return <Empty title="Could not load academic years" detail={programErrorMessage(years.error, "Could not load academic programs.")} />;
  if (editing && query.isError) return <Empty title="Could not load academic program" detail={programErrorMessage(query.error, "Could not load academic program.")} />;
