function RealAttendancePage({ session }: { session: User }) {
  const [academicYearId, setAcademicYearId] = useState("");
  const [classId, setClassId] = useState("");
  const [sectionId, setSectionId] = useState("");
  const [dateFilter, setDateFilter] = useState("");
  const years = useAcademicYears();
  const programs = usePrograms();
  const classes = useClasses();
  const sections = useSections();
  const query = useAttendance({ academicYearId: academicYearId || undefined, classId: classId || undefined, sectionId: sectionId || undefined, date: dateFilter || undefined });
  const canMark = hasPermission(session.role, "ATTENDANCE_MARK");
  if (query.isLoading || years.isLoading || programs.isLoading || classes.isLoading || sections.isLoading) return <><PageHeader title="Attendance" /><Loading /></>;
  if (query.isError || years.isError || programs.isError || classes.isError || sections.isError) return <><PageHeader title="Attendance" /><Empty title="Could not load attendance" detail={realAttendanceError(query.error || years.error || programs.error || classes.error || sections.error, "The attendance service is unavailable.")} action={<AppButton onClick={() => query.refetch()}>Try again</AppButton>} /></>;
  const yearNames = new Map((years.data || []).map((item) => [item.id, item.name]));
  const classNames = new Map((classes.data || []).map((item) => [item.id, item.name]));
  const sectionNames = new Map((sections.data || []).map((item) => [item.id, item.name]));
  const rows = query.data || [];
  return <><PageHeader title="Attendance" description="Daily class registers from the real Attendance service." action={canMark && <Link href="/attendance/mark" className="inline-flex h-10 items-center gap-2 rounded-lg bg-primary px-4 text-sm font-semibold text-primary-foreground"><Plus size={16} />Mark attendance</Link>} /><div className="list-toolbar"><label className="field"><span>Academic year</span><select value={academicYearId} onChange={(event) => { setAcademicYearId(event.target.value); setClassId(""); setSectionId(""); }}><option value="">All academic years</option>{(years.data || []).map((year) => <option key={year.id} value={year.id}>{year.name}</option>)}</select></label><label className="field"><span>Class</span><select value={classId} onChange={(event) => { setClassId(event.target.value); setSectionId(""); }}><option value="">All classes</option>{(classes.data || []).filter((item) => !academicYearId || (programs.data || []).some((program) => program.id === item.programId && program.academicYearId === academicYearId)).map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label className="field"><span>Section</span><select value={sectionId} onChange={(event) => setSectionId(event.target.value)}><option value="">All sections</option>{(sections.data || []).filter((item) => !classId || item.classId === classId).map((section) => <option key={section.id} value={section.id}>{section.name}</option>)}</select></label><label className="field"><span>Date</span><input type="date" value={dateFilter} onChange={(event) => setDateFilter(event.target.value)} /></label></div>{rows.length === 0 ? <Empty title="No attendance registers found" detail="Choose another filter or mark a new daily register." /> : <div className="table-card"><div className="table-scroll"><table><thead><tr><th>Date</th><th>Academic year</th><th>Class</th><th>Section</th><th>Status</th><th>Present</th><th>Absent</th><th>Staff</th></tr></thead><tbody>{rows.map((record) => <tr key={record.id}><td><Link className="table-link" href={`/attendance/${record.id}`}><strong>{date(record.date.slice(0, 10))}</strong></Link></td><td>{yearNames.get(record.academicYearId) || record.academicYearId}</td><td>{classNames.get(record.classId) || record.classId}</td><td>{sectionNames.get(record.sectionId) || record.classId}</td><td><Status>{record.status}</Status></td><td className="amount-positive">{record.children.filter((entry) => entry.status === "PRESENT").length}</td><td>{record.children.filter((entry) => entry.status === "ABSENT").length}</td><td>{record.takenBy}</td></tr>)}</tbody></table></div><div className="table-foot"><span>{rows.length} attendance registers</span><span className="table-foot-note">Real backend records</span></div></div>}</>;
}

function RealAttendanceMark({ id, session }: { id?: string; session: User }) {
  const editing = Boolean(id);
  const [selection, setSelection] = useState({ academicYearId: "", classId: "", sectionId: "", date: "" });
  const [entries, setEntries] = useState<{ studentId: string; status: StudentAttendanceStatus }[]>([]);
  const [error, setError] = useState("");
  const existing = useAttendanceRecord(id);
  const years = useAcademicYears();
  const programs = usePrograms();
  const classes = useClasses();
  const sections = useSectionsByClass(selection.classId);
  const students = useStudents();
  const calendar = useAcademicCalendar({ academicYearId: selection.academicYearId || undefined });
  const create = useCreateAttendance();
  const update = useUpdateAttendance();
  const [, setLocation] = useLocation();
  const canEdit = hasPermission(session.role, editing ? "ATTENDANCE_UPDATE" : "ATTENDANCE_MARK");
  const selectedYear = (years.data || []).find((year) => year.id === selection.academicYearId);
  const selectedClass = (classes.data || []).find((item) => item.id === selection.classId);
  const selectedSection = (sections.data || []).find((item) => item.id === selection.sectionId);
  const classOptions = (classes.data || []).filter((item) => !selection.academicYearId || (programs.data || []).some((program) => program.id === item.programId && program.academicYearId === selection.academicYearId));
  const eligibleStudents = (students.data || []).filter((student) => student.admission.academicYearId === selection.academicYearId && student.admission.classId === selection.classId && student.admission.sectionId === selection.sectionId);
  const calendarRecord = (calendar.data || []).find((item) => item.date.slice(0, 10) === selection.date);
  useEffect(() => { if (editing && existing.data) { setSelection({ academicYearId: existing.data.academicYearId, classId: existing.data.classId, sectionId: existing.data.sectionId, date: existing.data.date.slice(0, 10) }); setEntries(existing.data.children.map((entry) => ({ studentId: entry.studentId, status: entry.status }))); } }, [editing, existing.data]);
  useEffect(() => { if (!editing && !selection.academicYearId && years.data?.[0]) setSelection((current) => ({ ...current, academicYearId: years.data![0].id })); }, [editing, selection.academicYearId, years.data]);
  useEffect(() => { if (!editing && selection.academicYearId && selectedYear && !selection.date) setSelection((current) => ({ ...current, date: selectedYear.startDate.slice(0, 10) })); }, [editing, selectedYear, selection.academicYearId, selection.date]);
  useEffect(() => { if (!editing && eligibleStudents.length && entries.length === 0) setEntries(eligibleStudents.map((student) => ({ studentId: student.id, status: "PRESENT" }))); }, [editing, eligibleStudents, entries.length]);
  if (!canEdit) return <AccessState role={session.role} />;
  if (years.isLoading || programs.isLoading || classes.isLoading || students.isLoading || (selection.classId && sections.isLoading) || (editing && existing.isLoading)) return <Loading />;
  if (years.isError || programs.isError || classes.isError || students.isError || sections.isError || (editing && existing.isError)) return <Empty title="Could not load attendance form" detail={realAttendanceError(existing.error || years.error || programs.error || classes.error || sections.error || students.error, "The attendance form could not be loaded.")} />;
  if (editing && existing.data?.status === "SUBMITTED") return <Empty title="Attendance register is read-only" detail="Submitted attendance cannot be edited." action={<Link href={`/attendance/${id}`} className="text-button">Back to register</Link>} />;
  const updateSelection = (key: keyof typeof selection, value: string) => { setError(""); if (key === "academicYearId") setSelection({ academicYearId: value, classId: "", sectionId: "", date: "" }); else if (key === "classId") setSelection((current) => ({ ...current, classId: value, sectionId: "" })); else setSelection((current) => ({ ...current, [key]: value })); if (key !== "date") setEntries([]); };
  const setStatus = (studentId: string, status: StudentAttendanceStatus) => setEntries((current) => current.map((entry) => entry.studentId === studentId ? { ...entry, status } : entry));
  const submit = (event: FormEvent) => { event.preventDefault(); setError(""); if (!selection.academicYearId || !selection.classId || !selection.sectionId || !selection.date) { setError("Choose an academic year, class, section, and date."); return; } if (!entries.length) { setError("No eligible Students were found for this class and section."); return; } const payload = { academicYearId: selection.academicYearId, classId: selection.classId, sectionId: selection.sectionId, date: selection.date, entries }; const mutation = editing ? update.mutateAsync({ id: id!, payload: { entries } }) : create.mutateAsync(payload); mutation.then((saved) => { toast({ title: editing ? "Draft attendance updated" : "Attendance draft created", description: "Review the register before submitting it." }); setLocation(`/attendance/${saved.id}`); }).catch((reason) => setError(realAttendanceError(reason, "Could not save attendance."))); };
  const busy = create.isPending || update.isPending;
  return <><button className="back-link page-back" onClick={() => setLocation(editing ? `/attendance/${id}` : "/attendance")}><ArrowLeft size={15} />Back to Attendance</button><PageHeader eyebrow={editing ? "Edit draft" : "New draft"} title={editing ? "Edit attendance draft" : "Mark attendance"} description="Record Present or Absent for every eligible Student." />{error && <div className="mb-4 rounded-lg border border-red-200 bg-red-50 p-3 text-sm text-red-700" role="alert">{error}</div>}<form className="form-card attendance-form" onSubmit={submit}><div className="form-grid">{editing ? <><div className="field"><span>Academic year</span><strong>{selectedYear?.name || selection.academicYearId}</strong></div><div className="field"><span>Class</span><strong>{selectedClass?.name || selection.classId}</strong></div><div className="field"><span>Section</span><strong>{selectedSection?.name || selection.sectionId}</strong></div></> : <><label className="field"><span>Academic year</span><select value={selection.academicYearId} onChange={(event) => updateSelection("academicYearId", event.target.value)}><option value="">Select academic year</option>{(years.data || []).map((year) => <option key={year.id} value={year.id}>{year.name}</option>)}</select></label><label className="field"><span>Class</span><select value={selection.classId} onChange={(event) => updateSelection("classId", event.target.value)} disabled={!selection.academicYearId}><option value="">Select class</option>{classOptions.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label className="field"><span>Section</span><select value={selection.sectionId} onChange={(event) => updateSelection("sectionId", event.target.value)} disabled={!selection.classId}><option value="">Select section</option>{(sections.data || []).map((section) => <option key={section.id} value={section.id}>{section.name}</option>)}</select></label></>}<div className="field"><label htmlFor="attendance-date">Date</label><input id="attendance-date" type="date" min={selectedYear?.startDate.slice(0, 10)} max={selectedYear?.endDate.slice(0, 10)} value={selection.date} onChange={(event) => updateSelection("date", event.target.value)} /><span className="field-help">The backend requires an active working-day calendar record.</span>{calendarRecord && !calendarRecord.isWorkingDay && <span className="field-help text-red-700">This date is marked non-working.</span>}</div></div>{!editing && selection.classId && <div className="mt-4 text-sm text-muted-foreground">{eligibleStudents.length} eligible Students loaded from the real backend.</div>}<div className="attendance-list"><div className="attendance-list-head"><span>Student</span><span>Status</span></div>{(editing ? entries : eligibleStudents.map((student) => entries.find((entry) => entry.studentId === student.id) || { studentId: student.id, status: "PRESENT" as StudentAttendanceStatus })).map((entry) => { const student = (students.data || []).find((item) => item.id === entry.studentId); return <div className="attendance-row" key={entry.studentId}><span>{student ? `${student.studentName} · ${student.studentNumber}` : entry.studentId}</span><span className="attendance-controls"><button type="button" className={`attendance-choice ${entry.status === "PRESENT" ? "attendance-choice-present" : ""}`} onClick={() => setStatus(entry.studentId, "PRESENT")}>Present</button><button type="button" className={`attendance-choice ${entry.status === "ABSENT" ? "attendance-choice-absent" : ""}`} onClick={() => setStatus(entry.studentId, "ABSENT")}>Absent</button></span></div>; })}</div><div className="form-actions"><AppButton type="button" variant="ghost" onClick={() => setLocation(editing ? `/attendance/${id}` : "/attendance")}>Cancel</AppButton><AppButton type="submit" disabled={busy}>{busy ? "Saving…" : editing ? "Save draft changes" : "Create draft"}<ArrowRight size={16} /></AppButton></div></form></>;
}

function RealAttendanceDetail({ id, session }: { id: string; session: User }) {
  const query = useAttendanceRecord(id);
  const students = useStudents();
  const years = useAcademicYears();
  const classes = useClasses();
  const sections = useSections();
  const submit = useSubmitAttendance();
  const remove = useDeleteAttendance();
  const [, setLocation] = useLocation();
  if (query.isLoading || students.isLoading || years.isLoading || classes.isLoading || sections.isLoading) return <Loading />;
  if (query.isError || students.isError || years.isError || classes.isError || sections.isError) return <Empty title="Could not load attendance register" detail={realAttendanceError(query.error || students.error || years.error || classes.error || sections.error, "The attendance register could not be loaded.")} action={<Link href="/attendance" className="text-button">Back to Attendance</Link>} />;
  const item = query.data;
  if (!item) return <Empty title="Attendance register not found" detail="This register may have been removed." />;
  const year = (years.data || []).find((entry) => entry.id === item.academicYearId);
  const schoolClass = (classes.data || []).find((entry) => entry.id === item.classId);
  const section = (sections.data || []).find((entry) => entry.id === item.sectionId);
  const canUpdate = hasPermission(session.role, "ATTENDANCE_UPDATE") && item.status === "DRAFT";
  const canSubmit = hasPermission(session.role, "ATTENDANCE_MARK") && item.status === "DRAFT";
  const studentMap = new Map((students.data || []).map((student) => [student.id, student]));
  const runSubmit = () => { if (!window.confirm("Submit this attendance register? Submitted registers become read-only.")) return; submit.mutate(id, { onSuccess: () => toast({ title: "Attendance submitted" }), onError: (error) => toast({ title: "Could not submit attendance", description: realAttendanceError(error, "Please try again.") }) }); };
  const runDelete = () => { if (!window.confirm("Delete this draft attendance register?")) return; remove.mutate(id, { onSuccess: () => { toast({ title: "Attendance draft deleted" }); setLocation("/attendance"); }, onError: (error) => toast({ title: "Could not delete attendance", description: realAttendanceError(error, "Please try again.") }) }); };
  return <><button className="back-link page-back" onClick={() => setLocation("/attendance")}><ArrowLeft size={15} />Back to Attendance</button><PageHeader eyebrow="Attendance register" title={`${schoolClass?.name || item.classId} · Section ${section?.name || item.sectionId}`} description={`${date(item.date.slice(0, 10))} · ${year?.name || item.academicYearId} · Staff ${item.takenBy}`} action={<div className="detail-actions">{canUpdate && <Link href={`/attendance/${id}/edit`} className="inline-flex h-10 items-center gap-2 rounded-lg border border-border bg-card px-4 text-sm font-semibold"><Settings2 size={15} />Edit draft</Link>}{canSubmit && <AppButton onClick={runSubmit} disabled={submit.isPending}><Check size={15} />Submit</AppButton>}{canUpdate && <AppButton variant="danger" onClick={runDelete} disabled={remove.isPending}><X size={15} />Delete draft</AppButton>}</div>} /><div className="panel detail-panel mb-5"><div className="detail-fields">{[["Academic year", year?.name || item.academicYearId], ["Class", schoolClass?.name || item.classId], ["Section", section?.name || item.sectionId], ["Date", date(item.date.slice(0, 10))], ["Staff", item.takenBy], ["Status", item.status], ["Students", String(item.children.length)]].map(([label, value]) => <div className="detail-field" key={label}><span>{label}</span><strong>{value}</strong></div>)}</div></div><div className="table-card"><div className="table-scroll"><table><thead><tr><th>Student</th><th>Student number</th><th>Status</th></tr></thead><tbody>{item.children.map((entry) => { const student = studentMap.get(entry.studentId); return <tr key={entry.id}><td>{student?.studentName || entry.studentId}</td><td>{student?.studentNumber || "—"}</td><td><Status>{entry.status}</Status></td></tr>; })}</tbody></table></div><div className="table-foot"><span>{item.children.length} students</span><span className="table-foot-note">{item.status === "SUBMITTED" ? "Submitted and read-only" : "Draft register"}</span></div></div></>;
}

function TimetablePage() {
  const query = useResource("timetable"); if (query.isLoading) return <><PageHeader title="Timetable" /><Loading /></>;
  const days = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday"]; return <><PageHeader title="Timetable" description="Published teaching schedule for the current academic year." /><div className="timetable-scroll"><div className="timetable-grid">{days.map((day) => <section className="timetable-day" key={day}><div className="timetable-day-head"><span>{day.slice(0, 3)}</span><strong>{day}</strong></div>{(query.data || []).filter((entry) => entry.day === day).map((entry) => <div className="timetable-entry" key={entry.id}><div className="eyebrow">{entry.time}</div><strong>{entry.subject}</strong><span>{entry.class} · {entry.section}</span><small>{entry.faculty} · {entry.room}</small></div>)}{!(query.data || []).some((entry) => entry.day === day) && <div className="timetable-empty">No periods</div>}</section>)}</div></div></>;
}

function Profile({ session }: { session: User }) { return <><PageHeader eyebrow="Account" title="My profile" description="Your backend-authenticated identity." /><div className="profile-layout"><section className="panel profile-card"><Avatar user={session} size="lg" /><div className="eyebrow mt-5">Signed in as</div><h2>{session.name}</h2><p>{session.title}</p><div className="profile-details"><div><span>User ID</span><strong>{session.id}</strong></div><div><span>Email</span><strong>{session.email || "Not returned by /auth/me"}</strong></div><div><span>Permissions</span><strong>Resolved by backend RBAC for API requests</strong></div></div></section></div></>; }

function ParamSetupForm({ resource, session }: { resource: SetupResource; session: User }) { const { id } = useParams(); return <SetupForm resource={resource} id={id} session={session} />; }
function ParamSetupDetail({ resource, session }: { resource: SetupResource; session: User }) { const { id } = useParams(); return <SetupDetail resource={resource} id={id || ""} session={session} />; }
type AdmissionFormState = { academicYearId: string; programId: string; classId: string; sectionId: string; studentName: string; gender: string; dateOfBirth: string; parentName: string; parentRelation: string; parentPhone: string; parentAlternatePhone: string; parentEmail: string; addressLine1: string; addressLine2: string; city: string; state: string; country: string; postalCode: string };
const emptyAdmissionForm: AdmissionFormState = { academicYearId: "", programId: "", classId: "", sectionId: "", studentName: "", gender: "MALE", dateOfBirth: "", parentName: "", parentRelation: "FATHER", parentPhone: "", parentAlternatePhone: "", parentEmail: "", addressLine1: "", addressLine2: "", city: "", state: "", country: "India", postalCode: "" };
const admissionFormSchema = z.object({ academicYearId: z.string().min(1, "Academic year is required"), programId: z.string().min(1, "Program is required"), classId: z.string().min(1, "Class is required"), sectionId: z.string().min(1, "Section is required"), studentName: z.string().min(1, "Student name is required"), gender: z.string().min(1), dateOfBirth: z.string().min(1, "Date of birth is required"), parentName: z.string().min(1, "Parent name is required"), parentRelation: z.string().min(1), parentPhone: z.string().min(1, "Parent phone is required"), parentAlternatePhone: z.string(), parentEmail: z.string().email("Enter a valid parent email"), addressLine1: z.string().min(1, "Address is required"), addressLine2: z.string(), city: z.string().min(1, "City is required"), state: z.string().min(1, "State is required"), country: z.string().min(1, "Country is required"), postalCode: z.string().min(1, "Postal code is required") });
function admissionToForm(item: AdmissionResponse): AdmissionFormState { return { academicYearId: item.academicYearId, programId: item.programId, classId: item.classId, sectionId: item.sectionId, studentName: item.studentName, gender: item.gender, dateOfBirth: item.dateOfBirth?.slice(0, 10) || "", parentName: item.parentName || "", parentRelation: item.parentRelation || "FATHER", parentPhone: item.parentPhone || "", parentAlternatePhone: item.parentAlternatePhone || "", parentEmail: item.parentEmail || "", addressLine1: item.addressLine1 || "", addressLine2: item.addressLine2 || "", city: item.city || "", state: item.state || "", country: item.country || "India", postalCode: item.pincode || "" }; }
function admissionPayload(form: AdmissionFormState, years: AcademicYear[], userId: string): AdmissionPayload { const year = years.find((item) => item.id === form.academicYearId); return { ...form, schoolId: year?.schoolId || "", createdById: userId, feePaymentHeaders: { feePaymentDetails: [], totalFeeAmount: 0, grossAmount: 0, netAmount: 0, totalPaidAmount: 0, totalDueAmount: 0 } }; }
function AdmissionSelectors({ form, setForm, editing }: { form: AdmissionFormState; setForm: React.Dispatch<React.SetStateAction<AdmissionFormState>>; editing: boolean }) { const years = useAcademicYears(); const programs = usePrograms(); const classes = useClasses(); const sections = useSectionsByClass(form.classId); const set = (key: keyof AdmissionFormState, value: string) => setForm((current) => ({ ...current, [key]: value, ...(key === "academicYearId" ? { programId: "", classId: "", sectionId: "" } : key === "programId" ? { classId: "", sectionId: "" } : key === "classId" ? { sectionId: "" } : {}) })); return <div className="detail-grid"><AdmissionSelectField name="academicYearId" label="Academic year" options={[["", "Select academic year"], ...(years.data || []).map((item) => [item.id, item.name])]} value={form.academicYearId} onChange={(value) => set("academicYearId", value)} disabled={editing} /><AdmissionSelectField name="programId" label="Program" options={[["", "Select program"], ...(programs.data || []).filter((item) => item.academicYearId === form.academicYearId).map((item) => [item.id, item.name])]} value={form.programId} onChange={(value) => set("programId", value)} disabled={!form.academicYearId} /><AdmissionSelectField name="classId" label="Class" options={[["", "Select class"], ...(classes.data || []).filter((item) => item.programId === form.programId).map((item) => [item.id, item.name])]} value={form.classId} onChange={(value) => set("classId", value)} disabled={!form.programId} /><AdmissionSelectField name="sectionId" label="Section" options={[["", "Select section"], ...(sections.data || []).map((item) => [item.id, item.name])]} value={form.sectionId} onChange={(value) => set("sectionId", value)} disabled={!form.classId} /></div>; }
function AdmissionSelectField({ name, label, options, value, onChange, disabled = false }: { name: string; label: string; options: string[][]; value: string; onChange: (value: string) => void; disabled?: boolean }) { return <div className="field"><label htmlFor={name}>{label}</label><select id={name} value={value} disabled={disabled} onChange={(event) => onChange(event.target.value)}>{options.map(([option, text]) => <option key={option} value={option}>{text}</option>)}</select></div>; }
function AdmissionForm({ session, id }: { session: User; id?: string }) { const editing = Boolean(id); const itemQuery = useAdmission(id); const years = useAcademicYears(); const save = useSaveAdmission(id); const [, setLocation] = useLocation(); const [form, setForm] = useState(emptyAdmissionForm); const [error, setError] = useState(""); useEffect(() => { if (itemQuery.data) setForm(admissionToForm(itemQuery.data)); }, [itemQuery.data]); const update = (key: keyof AdmissionFormState) => (event: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => setForm((current) => ({ ...current, [key]: event.target.value })); const submit = async (event: FormEvent) => { event.preventDefault(); setError(""); const parsed = admissionFormSchema.safeParse(form); if (!parsed.success) { setError(parsed.error.issues[0]?.message || "Please complete the form"); return; } if (!years.data?.find((year) => year.id === form.academicYearId)?.schoolId) { setError("The selected academic year has no school configured."); return; } try { const payload = admissionPayload(form, years.data || [], session.id); if (editing) { const { schoolId: _schoolId, academicYearId: _academicYearId, createdById: _createdById, ...updatePayload } = payload; await save.mutateAsync({ ...updatePayload, admissionId: id! }); } else { await save.mutateAsync(payload); } toast({ title: editing ? "Admission updated" : "Admission created" }); setLocation("/admissions"); } catch (reason) { setError(admissionErrorMessage(reason, "Could not save admission.")); } }; if (editing && itemQuery.isLoading) return <Loading />; if (editing && !itemQuery.data) return <Empty title="Admission not found" detail="The requested admission could not be loaded." />; return <><PageHeader title={editing ? "Edit admission" : "New admission"} description="Capture the student, guardian, and academic placement details." /><form onSubmit={submit} className="panel space-y-5"><h2>Academic placement</h2><AdmissionSelectors form={form} setForm={setForm} editing={editing} /><h2>Student / applicant</h2><div className="form-grid"><FieldValue label="Student name" value={form.studentName} onChange={update("studentName")} /><SelectField name="gender" label="Gender" options={[["MALE", "Male"], ["FEMALE", "Female"], ["OTHER", "Other"]]} value={form.gender} onChange={(value) => setForm((current) => ({ ...current, gender: value }))} /><FieldValue label="Date of birth" type="date" value={form.dateOfBirth} onChange={update("dateOfBirth")} /></div><h2>Parent / guardian</h2><div className="form-grid"><FieldValue label="Parent name" value={form.parentName} onChange={update("parentName")} /><SelectField name="parentRelation" label="Relation" options={[["FATHER", "Father"], ["MOTHER", "Mother"], ["GUARDIAN", "Guardian"]]} value={form.parentRelation} onChange={(value) => setForm((current) => ({ ...current, parentRelation: value }))} /><FieldValue label="Parent phone" value={form.parentPhone} onChange={update("parentPhone")} /><FieldValue label="Alternate phone" value={form.parentAlternatePhone} onChange={update("parentAlternatePhone")} /><FieldValue label="Parent email" type="email" value={form.parentEmail} onChange={update("parentEmail")} /></div><h2>Address</h2><div className="form-grid"><FieldValue label="Address line 1" value={form.addressLine1} onChange={update("addressLine1")} /><FieldValue label="Address line 2" value={form.addressLine2} onChange={update("addressLine2")} /><FieldValue label="City" value={form.city} onChange={update("city")} /><FieldValue label="State" value={form.state} onChange={update("state")} /><FieldValue label="Country" value={form.country} onChange={update("country")} /><FieldValue label="Postal code" value={form.postalCode} onChange={update("postalCode")} /></div>{error && <p className="field-error" role="alert">{error}</p>}<div className="detail-actions"><AppButton type="submit" disabled={save.isPending}>{save.isPending ? "Saving…" : editing ? "Save changes" : "Create admission"}</AppButton><AppButton type="button" variant="ghost" onClick={() => setLocation("/admissions")}>Cancel</AppButton></div></form></>; }
function FieldValue({ label, value, onChange, type = "text" }: { label: string; value: string; onChange: (event: React.ChangeEvent<HTMLInputElement>) => void; type?: string }) { return <div className="field"><label>{label}</label><input required={label !== "Address line 2" && label !== "Alternate phone"} type={type} value={value} onChange={onChange} /></div>; }
function AdmissionList({ session }: { session: User }) { const query = useAdmissions(); const [search, setSearch] = useState(""); const [filter, setFilter] = useState("All"); const years = useAcademicYears(); const programs = usePrograms(); const classes = useClasses(); const sections = useSections(); const [, setLocation] = useLocation(); if (query.isLoading) return <><PageHeader title="Admissions" /><Loading /></>; if (query.isError) return <Empty title="Could not load admissions" detail={admissionErrorMessage(query.error, "The admissions service is unavailable.")} />; const rows = (query.data || []).filter((item) => { const text = `${item.admissionNumber} ${item.studentName}`.toLowerCase(); return text.includes(search.toLowerCase()) && (filter === "All" || admissionStatusLabel(item.admissionStatus) === filter); }); const label = (id: string, values: Array<{ id: string; name: string }>) => values.find((value) => value.id === id)?.name || id; return <><PageHeader title="Admissions" description="Track applications from first contact to confirmation." action={hasPermission(session.role, "ADMISSION_CREATE") ? <Link href="/admissions/new" className="inline-flex h-10 items-center gap-2 rounded-lg bg-primary px-4 text-sm font-semibold text-primary-foreground"><Plus size={16} />Add application</Link> : undefined} /><div className="list-toolbar"><SearchBox value={search} onChange={setSearch} /><SelectBox value={filter} onChange={setFilter} label="Status" options={["Pending", "Confirmed", "Cancelled"]} /></div>{rows.length === 0 ? <Empty title="No admissions found" detail="Try a different search or clear the current filter." /> : <div className="table-card"><div className="table-scroll"><table><thead><tr><th>Admission no.</th><th>Student</th><th>Academic placement</th><th>Status</th><th /></tr></thead><tbody>{rows.map((item) => <tr key={item.id}><td><Link href={`/admissions/${item.id}`} className="table-link">{item.admissionNumber}</Link></td><td>{item.studentName}</td><td>{label(item.academicYearId, years.data || [])} · {label(item.programId, programs.data || [])} · {label(item.classId, classes.data || [])} · {label(item.sectionId, sections.data || [])}</td><td><Status>{admissionStatusLabel(item.admissionStatus)}</Status></td><td className="row-actions"><Link href={`/admissions/${item.id}/edit`} className="icon-button" title="Edit admission"><Settings2 size={15} /></Link></td></tr>)}</tbody></table></div><div className="table-foot"><span>Showing {rows.length} of {rows.length} records</span><span className="table-foot-note">Click an admission to view details</span></div></div>}</>; }
function AdmissionDetail({ session, id }: { session: User; id: string }) { const query = useAdmission(id); const workflow = useAdmissionWorkflow(); const [, setLocation] = useLocation(); const years = useAcademicYears(); const programs = usePrograms(); const classes = useClasses(); const sections = useSections(); const [error, setError] = useState(""); if (query.isLoading) return <Loading />; if (query.isError || !query.data) return <Empty title="Admission not found" detail={admissionErrorMessage(query.error, "The requested admission could not be loaded.")} />; const item = query.data; const label = (value: string, values: Array<{ id: string; name: string }>) => values.find((entry) => entry.id === value)?.name || value; const run = async (action: "confirm" | "cancel") => { if (!window.confirm(action === "confirm" ? "Confirming creates a real Student record. Continue?" : "Cancel this admission? This cannot be reopened here.")) return; try { await workflow.mutateAsync({ id, action }); toast({ title: action === "confirm" ? "Admission confirmed" : "Admission cancelled" }); } catch (reason) { setError(admissionErrorMessage(reason, "Could not update admission.")); } }; const status = admissionStatusLabel(item.admissionStatus); return <><button className="back-link page-back" onClick={() => setLocation("/admissions")}><ArrowLeft size={15} />Back to Admissions</button><PageHeader title={item.studentName} description={`${item.admissionNumber} · ${status}`} action={<div className="detail-actions"><Link href={`/admissions/${id}/edit`} className="inline-flex h-10 items-center gap-2 rounded-lg border border-border bg-card px-4 text-sm font-semibold"><Settings2 size={15} />Edit</Link>{status === "Pending" && hasPermission(session.role, "ADMISSION_UPDATE") && <><AppButton variant="soft" onClick={() => run("confirm")} disabled={workflow.isPending}><Check size={15} />Confirm</AppButton><AppButton variant="danger" onClick={() => run("cancel")} disabled={workflow.isPending}><X size={15} />Cancel</AppButton></>}</div>} /><section className="panel"><div className="panel-head"><h2>Admission details</h2><Status>{status}</Status></div><div className="detail-fields">{[["Admission number", item.admissionNumber], ["Student name", item.studentName], ["Gender", item.gender], ["Date of birth", date(item.dateOfBirth?.slice(0, 10))], ["Academic year", label(item.academicYearId, years.data || [])], ["Program", label(item.programId, programs.data || [])], ["Class", label(item.classId, classes.data || [])], ["Section", label(item.sectionId, sections.data || [])], ["Parent", item.parentName], ["Parent relation", item.parentRelation], ["Parent phone", item.parentPhone], ["Parent email", item.parentEmail], ["Address", [item.addressLine1, item.addressLine2, item.city, item.state, item.country, item.pincode].filter(Boolean).join(", ")], ["Student ID", item.studentId]].map(([key, value]) => <div className="detail-field" key={key}><span>{key}</span><strong>{String(value || "—")}</strong></div>)}</div>{error && <p className="field-error" role="alert">{error}</p>}</section></>; }
function ParamBasicForm({ resource, session }: { resource: BasicResource; session: User }) { const { id } = useParams(); return resource === "admissions" ? <AdmissionForm id={id} session={session} /> : <BasicForm resource={resource} id={id} session={session} />; }
function studentLabel(id: string, values: Array<{ id: string; name: string }>) { return values.find((value) => value.id === id)?.name || id; }
function StudentList({ session }: { session: User }) { const query = useStudents(); const [search, setSearch] = useState(""); const years = useAcademicYears(); const programs = usePrograms(); const classes = useClasses(); const sections = useSections(); if (query.isLoading) return <><PageHeader title="Students" /><Loading /></>; if (query.isError) return <Empty title="Could not load students" detail={studentErrorMessage(query.error, "The student service is unavailable.")} />; const rows = (query.data || []).map((student) => ({ student, year: studentLabel(student.admission.academicYearId, years.data || []), program: studentLabel(student.admission.programId, programs.data || []), className: studentLabel(student.admission.classId, classes.data || []), section: studentLabel(student.admission.sectionId, sections.data || []) })).filter(({ student, year, program, className, section }) => `${student.studentNumber} ${student.studentName} ${student.admissionId} ${year} ${program} ${className} ${section}`.toLowerCase().includes(search.toLowerCase())); return <><PageHeader title="Students" description="The enrolled student register from the real backend." action={hasPermission(session.role, "STUDENT_CREATE") ? <Link href="/students/new" className="inline-flex h-10 items-center gap-2 rounded-lg border border-border bg-card px-4 text-sm font-semibold">Add student (legacy)</Link> : undefined} /><div className="list-toolbar"><SearchBox value={search} onChange={setSearch} /><span className="muted-note">{rows.length} records</span></div>{rows.length === 0 ? <Empty title="No students found" detail="Try a different search." /> : <div className="table-card"><div className="table-scroll"><table><thead><tr><th>Student number</th><th>Student</th><th>Academic year</th><th>Program</th><th>Class</th><th>Section</th><th>Gender</th><th>Date of birth</th></tr></thead><tbody>{rows.map(({ student, year, program, className, section }) => <tr key={student.id}><td><Link href={`/students/${student.id}`} className="table-link">{student.studentNumber}</Link></td><td>{student.studentName}</td><td>{year}</td><td>{program}</td><td>{className}</td><td>{section}</td><td>{student.gender}</td><td>{date(student.dateOfBirth.slice(0, 10))}</td></tr>)}</tbody></table></div><div className="table-foot"><span>Showing {rows.length} of {rows.length} records</span><span className="table-foot-note">Click a student number to view details</span></div></div>}</>; }
function StudentDetail({ id }: { id: string }) { const query = useStudent(id); const fees = useStudentFees(id); const admission = useAdmission(query.data?.admissionId); const years = useAcademicYears(); const programs = usePrograms(); const classes = useClasses(); const sections = useSections(); const [, setLocation] = useLocation(); const [paymentAmount, setPaymentAmount] = useState(""); const [paymentDate, setPaymentDate] = useState(""); const [recording, setRecording] = useState(false); const submitPayment = async () => { const parsed = Number(paymentAmount); if (!Number.isFinite(parsed) || parsed <= 0) { toast({ title: "Invalid payment", description: "Enter a number greater than zero." }); return; } setRecording(true); try { await studentFeesApi.createPayment(id, { amount: parsed, paymentDate: paymentDate || undefined }); toast({ title: "Payment recorded", description: "The student fee snapshot has been refreshed." }); setPaymentAmount(""); setPaymentDate(""); await fees.refetch(); } catch (error) { toast({ title: "Could not record payment", description: studentFeesErrorMessage(error, "Please try again later.") }); } finally { setRecording(false); } }; if (query.isLoading) return <Loading />; if (query.isError || !query.data) return <Empty title="Student not found" detail={studentErrorMessage(query.error, "The requested student could not be loaded.")} />; const student = query.data; const placement = student.admission; const admissionRecord = admission.data; const feeState = fees.data?.fee; const payments = fees.data?.payments || []; return <><button className="back-link page-back" onClick={() => setLocation("/students")}><ArrowLeft size={15} />Back to Students</button><PageHeader title={student.studentName} description={`${student.studentNumber} · Read-only backend record`} /><section className="panel"><div className="panel-head"><h2>Student details</h2></div><div className="detail-fields">{[["Student number", student.studentNumber], ["Student sequence", String(student.studentSequence)], ["Student name", student.studentName], ["Gender", student.gender], ["Date of birth", date(student.dateOfBirth.slice(0, 10))], ["Created", date(student.createdAt.slice(0, 10))], ["Updated", date(student.updatedAt.slice(0, 10))], ["Admission ID", student.admissionId], ["Admission number", admissionRecord?.admissionNumber], ["Admission status", admissionRecord ? admissionStatusLabel(admissionRecord.admissionStatus) : undefined], ["Academic year", studentLabel(placement.academicYearId, years.data || [])], ["Program", studentLabel(placement.programId, programs.data || [])], ["Class", studentLabel(placement.classId, classes.data || [])], ["Section", studentLabel(placement.sectionId, sections.data || [])], ["School ID", placement.schoolId]].map(([key, value]) => <div className="detail-field" key={key}><span>{key}</span><strong>{String(value || "—")}</strong></div>)}</div><p className="muted-note mt-5">Student records are read-only until the backend write contract is implemented.</p></section>{fees.isLoading ? <div className="mt-6"><Loading label="Loading fee snapshot" /></div> : fees.isError ? <div className="mt-6"><Empty title="Could not load fee snapshot" detail={studentFeesErrorMessage(fees.error, "The live fee snapshot is unavailable.")} /></div> : <div className="mt-6 grid gap-6 lg:grid-cols-[1.5fr_1fr]"><section className="panel"><div className="panel-head"><div><div className="eyebrow">Student fee snapshot</div><h2>{feeState ? feeState.totalAmount ? money(feeAmount(feeState.totalAmount)) : "No fee snapshot" : "No fee snapshot"}</h2></div>{feeState && <Status>{feeState.outstandingAmount && Number(feeState.outstandingAmount) > 0 ? "Partial" : "Paid"}</Status>}</div>{feeState ? <><div className="detail-fields">{[["Fee structure", feeState.feeStructureId], ["Academic year", feeState.academicYearId], ["Total amount", money(feeAmount(feeState.totalAmount))], ["Paid amount", money(feeAmount(feeState.paidAmount))], ["Outstanding amount", money(feeAmount(feeState.outstandingAmount))]].map(([label, value]) => <div className="detail-field" key={label}><span>{label}</span><strong>{String(value)}</strong></div>)}</div><div className="mt-5 space-y-3">{feeState.components.map((component) => <div className="payment-line" key={component.id}><span><strong>{component.nameSnapshot}</strong><small>{component.isMandatory ? "Mandatory" : "Optional"} · {component.discountApplicable ? "Discountable" : "Fixed"}</small></span><div className="text-right"><strong>{money(feeAmount(component.finalAmount))}</strong><small className="block text-muted-foreground">Paid {money(feeAmount(component.amountPaid))} · Outstanding {money(feeAmount(component.amountOutstanding))}</small></div></div>)}</div></> : <p className="muted-note mt-4">No live fee snapshot exists for this admission yet.</p>}</section><aside className="panel"><div className="panel-head"><div><div className="eyebrow">Record payment</div><h2>Quick payment</h2></div></div><div className="space-y-4"><div className="field"><label htmlFor="student-fee-amount">Amount (INR)</label><input id="student-fee-amount" type="number" min="1" step="1" value={paymentAmount} onChange={(event) => setPaymentAmount(event.target.value)} /></div><div className="field"><label htmlFor="student-fee-date">Payment date</label><input id="student-fee-date" type="date" value={paymentDate} onChange={(event) => setPaymentDate(event.target.value)} /></div><AppButton onClick={submitPayment} disabled={recording || !feeState} className="w-full">{recording ? "Recording…" : "Record payment"}</AppButton>{payments.length > 0 && <div className="mt-4"><div className="eyebrow">Recent payments</div><div className="space-y-3 mt-2">{payments.slice(0, 5).map((payment) => <div className="payment-line" key={payment.id}><span><strong>{money(feeAmount(payment.amount))}</strong><small>{payment.paymentDate ? date(payment.paymentDate) : "No date"}</small></span><small className="text-muted-foreground">{payment.createdAt ? date(payment.createdAt.slice(0,10)) : ""}</small></div>)}</div></div>}</div></aside></div>}</>; }
function AdmissionDetailWithStudent({ id, session }: { id: string; session: User }) { const query = useAdmission(id); return <><AdmissionDetail id={id} session={session} />{query.data?.student?.id && <div className="mt-4"><Link href={`/students/${query.data.student.id}`} className="inline-flex h-10 items-center gap-2 rounded-lg bg-secondary px-4 text-sm font-semibold text-secondary-foreground">View Student</Link></div>}</>; }
function ParamBasicDetail({ resource, session }: { resource: BasicResource; session: User }) { const { id } = useParams(); return resource === "admissions" ? <AdmissionDetailWithStudent id={id || ""} session={session} /> : resource === "students" ? <StudentDetail id={id || ""} /> : <BasicDetail resource={resource} id={id || ""} session={session} />; }
function ParamAdmissionList({ session }: { session: User }) { return <AdmissionList session={session} />; }
function ParamFeeForm({ session }: { session: User }) { const { id } = useParams(); return <FeeForm id={id} session={session} />; }
function ParamRealFeeDetail({ session }: { session: User }) { const { id } = useParams(); return <RealFeeDetail id={id || ""} session={session} />; }
function ParamComponentForm({ session }: { session: User }) { const { id } = useParams(); return <FeeComponentForm id={id} session={session} />; }
function ParamRealFeeComponentDetail({ session }: { session: User }) { const { id } = useParams(); return <RealFeeComponentDetail id={id || ""} session={session} />; }
function ParamAttendanceMark({ session }: { session: User }) { const { id } = useParams(); return <RealAttendanceMark id={id} session={session} />; }
function ParamAttendanceDetail({ session }: { session: User }) { const { id } = useParams(); return <RealAttendanceDetail id={id || ""} session={session} />; }
function AcademicYearEditRoute() { const { id } = useParams(); return <AcademicYearForm id={id} />; }
function AcademicYearDetailRoute() { const { id } = useParams(); return <AcademicYearDetail id={id || ""} />; }
function AcademicCalendarEditRoute() { const { id } = useParams(); return <AcademicCalendarForm id={id} />; }
function AcademicCalendarDetailRoute({ session }: { session: User }) { const { id } = useParams(); return <AcademicCalendarDetail id={id || ""} session={session} />; }
function ProgramEditRoute() { const { id } = useParams(); return <ProgramForm id={id} />; }
function ProgramDetailRoute() { const { id } = useParams(); return <ProgramDetail id={id || ""} />; }
function ClassDetailRoute({ session }: { session: User }) { const { id } = useParams(); return <ClassDetail id={id || ""} session={session} />; }
function SectionDetailRoute({ session }: { session: User }) { const { id } = useParams(); return <SectionDetail id={id || ""} session={session} />; }
function SubjectDetailRoute({ session }: { session: User }) { const { id } = useParams(); return <SubjectDetail id={id || ""} session={session} />; }
function StaffDetailRoute({ session }: { session: User }) { const { id } = useParams(); return <StaffDetail id={id || ""} session={session} />; }
function TeachingAssignmentFormRoute({ session }: { session: User }) { const { id } = useParams(); return <TeachingAssignmentForm id={id} session={session} />; }

function RoutedApp({ session, onLogout }: { session: User; onLogout: () => void }) {
  return <Shell session={session} onLogout={onLogout}><Switch>
    <Route path="/dashboard"><Dashboard session={session} /></Route>
    <Route path="/academic-years/new"><AcademicYearForm /></Route><Route path="/academic-years/:id/edit"><AcademicYearEditRoute /></Route><Route path="/academic-years/:id"><AcademicYearDetailRoute /></Route><Route path="/academic-years"><AcademicYearsList /></Route>
    <Route path="/academic-calendar/new"><Protected session={session} permission="SHIFT_CREATE"><AcademicCalendarForm /></Protected></Route><Route path="/academic-calendar/:id/edit"><Protected session={session} permission="SHIFT_UPDATE"><AcademicCalendarEditRoute /></Protected></Route><Route path="/academic-calendar/:id"><Protected session={session} permission="SHIFT_READ"><AcademicCalendarDetailRoute session={session} /></Protected></Route><Route path="/academic-calendar"><Protected session={session} permission="SHIFT_READ"><AcademicCalendarList session={session} /></Protected></Route>
    <Route path="/academic-programs/new"><ProgramForm /></Route><Route path="/academic-programs/:id/edit"><ProgramEditRoute /></Route><Route path="/academic-programs/:id"><ProgramDetailRoute /></Route><Route path="/academic-programs"><ProgramsList /></Route>
    <Route path="/classes/new"><Protected session={session} permission="CLASS_CREATE"><ClassForm session={session} /></Protected></Route><Route path="/classes/:id/edit"><Protected session={session} permission="CLASS_UPDATE"><ClassForm session={session} /></Protected></Route><Route path="/classes/:id"><Protected session={session} permission="CLASS_READ"><ClassDetailRoute session={session} /></Protected></Route><Route path="/classes"><Protected session={session} permission="CLASS_READ"><ClassList session={session} /></Protected></Route>
    <Route path="/sections/new"><Protected session={session} permission="CLASS_CREATE"><SectionForm session={session} /></Protected></Route><Route path="/sections/:id/edit"><Protected session={session} permission="CLASS_UPDATE"><SectionForm session={session} /></Protected></Route><Route path="/sections/:id"><Protected session={session} permission="CLASS_READ"><SectionDetailRoute session={session} /></Protected></Route><Route path="/sections"><Protected session={session} permission="CLASS_READ"><SectionList session={session} /></Protected></Route>
    <Route path="/subjects/new"><Protected session={session} permission="CLASS_CREATE"><SubjectForm session={session} /></Protected></Route><Route path="/subjects/:id/edit"><Protected session={session} permission="CLASS_UPDATE"><SubjectForm session={session} /></Protected></Route><Route path="/subjects/:id"><Protected session={session} permission="CLASS_READ"><SubjectDetailRoute session={session} /></Protected></Route><Route path="/subjects"><Protected session={session} permission="CLASS_READ"><SubjectList session={session} /></Protected></Route>
    <Route path="/teaching-assignments/new"><Protected session={session} permission="STAFF_UPDATE"><TeachingAssignmentForm session={session} /></Protected></Route><Route path="/teaching-assignments/:id/edit"><Protected session={session} permission="STAFF_UPDATE"><TeachingAssignmentFormRoute session={session} /></Protected></Route><Route path="/teaching-assignments"><Protected session={session} permission="STAFF_READ"><TeachingAssignmentsList session={session} /></Protected></Route>
    <Route path="/students/new"><Protected session={session} permission="STUDENT_CREATE"><BasicForm resource="students" session={session} /></Protected></Route><Route path="/students/:id/edit"><Protected session={session} permission="STUDENT_UPDATE"><ParamBasicForm resource="students" session={session} /></Protected></Route><Route path="/students/:id"><Protected session={session} permission="STUDENT_READ"><ParamBasicDetail resource="students" session={session} /></Protected></Route><Route path="/students"><Protected session={session} permission="STUDENT_READ"><StudentList session={session} /></Protected></Route>
    <Route path="/admissions/new"><Protected session={session} permission="ADMISSION_CREATE"><AdmissionForm session={session} /></Protected></Route><Route path="/admissions/:id/edit"><Protected session={session} permission="ADMISSION_UPDATE"><ParamBasicForm resource="admissions" session={session} /></Protected></Route><Route path="/admissions/:id"><Protected session={session} permission="ADMISSION_READ"><ParamBasicDetail resource="admissions" session={session} /></Protected></Route><Route path="/admissions"><Protected session={session} permission="ADMISSION_READ"><ParamAdmissionList session={session} /></Protected></Route>
    <Route path="/staff/new"><Protected session={session} permission="STAFF_CREATE"><StaffForm session={session} /></Protected></Route><Route path="/staff/:id/edit"><Protected session={session} permission="STAFF_UPDATE"><StaffForm session={session} /></Protected></Route><Route path="/staff/:id"><Protected session={session} permission="STAFF_READ"><StaffDetailRoute session={session} /></Protected></Route><Route path="/staff"><Protected session={session} permission="STAFF_READ"><StaffList session={session} /></Protected></Route>
    <Route path="/fees/new"><Protected session={session} permission="FEES_CREATE"><FeeForm session={session} /></Protected></Route><Route path="/fees/:id/edit"><Protected session={session} permission="FEES_UPDATE"><ParamFeeForm session={session} /></Protected></Route><Route path="/fees/:id"><Protected session={session} permission="FEES_READ"><ParamRealFeeDetail session={session} /></Protected></Route><Route path="/fees"><Protected session={session} permission="FEES_READ"><RealFeesPage session={session} /></Protected></Route>
    <Route path="/fee-components/new"><Protected session={session} permission="FEES_CREATE"><FeeComponentForm session={session} /></Protected></Route><Route path="/fee-components/:id/edit"><Protected session={session} permission="FEES_UPDATE"><ParamComponentForm session={session} /></Protected></Route><Route path="/fee-components/:id"><Protected session={session} permission="FEES_READ"><ParamRealFeeComponentDetail session={session} /></Protected></Route><Route path="/fee-components"><Protected session={session} permission="FEES_READ"><RealFeeComponentsPage session={session} /></Protected></Route>
    <Route path="/attendance/mark"><Protected session={session} permission="ATTENDANCE_MARK"><RealAttendanceMark session={session} /></Protected></Route><Route path="/attendance/:id/edit"><Protected session={session} permission="ATTENDANCE_UPDATE"><ParamAttendanceMark session={session} /></Protected></Route><Route path="/attendance/:id"><Protected session={session} permission="ATTENDANCE_READ"><ParamAttendanceDetail session={session} /></Protected></Route><Route path="/attendance"><Protected session={session} permission="ATTENDANCE_READ"><RealAttendancePage session={session} /></Protected></Route>
    <Route path="/timetable"><Protected session={session} permission="TIMETABLE_READ"><TimetablePage /></Protected></Route><Route path="/profile"><Profile session={session} /></Route><Route path="/"><RedirectTo href="/dashboard" /></Route><Route component={NotFound} />
  </Switch></Shell>;
}

function Router() {
  const token = session.hasSession(); const currentUser = useCurrentUser(); const logout = useLogout();
  if (token && currentUser.isLoading) return <Loading label="Restoring session" />;
  if (token && currentUser.isError) return <SessionError error={currentUser.error} />;
  if (!token || !currentUser.data) return <Switch><Route path="/forgot-password" component={ForgotPassword} /><Route path="/reset-password" component={ResetPassword} /><Route path="/login" component={Login} /><Route><RedirectTo href="/login" /></Route></Switch>;
  const authenticatedUser = authUserToUiUser(currentUser.data);
  return <Switch><Route path="/login"><RedirectTo href="/dashboard" /></Route><Route><RoutedApp session={authenticatedUser} onLogout={() => { logout(); toast({ title: "Signed out", description: "Your session has ended." }); }} /></Route></Switch>;
}
function App() { return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, "")}><ErrorBoundary><Router /></ErrorBoundary></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>; }
export default App;
